SELECT student_id AS studentId, student_name AS studentName, class_name AS className, openid, password, phone
FROM students 
WHERE student_id = #{studentId}

SELECT student_id AS studentId, student_name AS studentName, class_name AS className, openid, password, phone
FROM students 
WHERE student_id = #{studentId} AND student_name = #{studentName}

SELECT student_id AS studentId, student_name AS studentName, class_name AS className, openid, password, phone
FROM students
WHERE student_id = #{studentId} AND phone = #{phone}

SELECT student_id AS studentId, student_name AS studentName, class_name AS className, openid, password, phone
FROM students 
WHERE class_name = #{className}
